-- Modify "categories" table
ALTER TABLE `categories` MODIFY COLUMN `name` varchar(100) NOT NULL;
-- Create "supply_catalog_snapshots" table
CREATE TABLE `supply_catalog_snapshots` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, `subsite_id` bigint unsigned NOT NULL DEFAULT 0, `token` varchar(36) NOT NULL, `connection_id` bigint unsigned NOT NULL, `identity` varchar(64) NOT NULL, `status` varchar(20) NOT NULL DEFAULT "pending", `lease_token` varchar(255) NOT NULL DEFAULT "", `lease_until` bigint NOT NULL DEFAULT 0, `expires_at` bigint NOT NULL, `attempts` bigint NOT NULL DEFAULT 0, `loaded_count` bigint NOT NULL DEFAULT 0, `message` varchar(500) NOT NULL DEFAULT "", `payload` json NULL, PRIMARY KEY (`id`), INDEX `supplycatalogsnapshot_connection_id_subsite_id_created_at` (`connection_id`, `subsite_id`, `created_at`), INDEX `supplycatalogsnapshot_expires_at` (`expires_at`), INDEX `supplycatalogsnapshot_status_lease_until` (`status`, `lease_until`), UNIQUE INDEX `token` (`token`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
